import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Week 3 — Context Engineering","description":"","frontmatter":{"source":"weeks/03-context-engineering/README.md"},"headers":[],"relativePath":"weeks/03-context-engineering/index.md","filePath":"weeks/03-context-engineering/index.md"}'),n={name:"weeks/03-context-engineering/index.md"};function s(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-3--context-engineering" tabindex="-1">Week 3 — Context Engineering <a class="header-anchor" href="#week-3--context-engineering" aria-label="Permalink to &quot;Week 3 — Context Engineering&quot;">​</a></h1><blockquote><p>An agent can work only from what&#39;s in its context, so decide what goes in, measure whether it gets used, and remember that instructions are advice, not enforcement.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Read the reading, post your reading response on Canvas, submit the week 2 onboarding report (the Seminar opens with its quiz); if a graduate paper is presented, post one question (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on the onboarding report (7 min, 🔴 AI off) · talk: <code>AGENTS.md</code>, rules, skills, MCP, context rot, the config-file evidence (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-03.html" target="_blank" rel="noreferrer">slides</a>) · first graduate presentation or reading discussion · demo: one MCP tool call · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--mcp-from-scratch-75-min">MCP from scratch</a>: run the server and client, read the JSON-RPC exchange, add a second tool with validation and tests, register it with an agent. <strong>Checkoff:</strong> an agent calls <em>your</em> new tool</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--agentsmd-and-an-ab-test">assignment</a> — an <code>AGENTS.md</code> for the class codebase and an A/B test of whether an agent follows it, plus the lab&#39;s second tool and tests</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: MCP server code and tests, the agent runs in your A/B test · 🟡 AI limited: your <code>AGENTS.md</code> (you write it; AI may critique it, logged) · 🔴 AI off: quiz, reading response, scoring runs</td></tr><tr><td><strong>Reading</strong></td><td>Denisov-Blanch et al., <a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">&quot;A Few Pages of Markdown&quot;</a> (preprint, Sep 2026)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (prompt <a href="#reading">below</a>)</td></tr><tr><td><strong>Team project</strong></td><td><code>course/TEAM_CHARTER.md</code> is in your team fork; start comparing teammates&#39; <code>AGENTS.md</code> drafts (the team merges one by M0, <a href="./../../project/milestones.html">milestones</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>Paper presentations begin: one per Seminar from this week (<a href="./../../graduate/paper-presentations.html">paper presentations</a>)</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain what an agent&#39;s <a href="./../../resources/glossary.html#context-engineering">context</a> holds each turn and why more context can make it worse (<a href="./../../resources/glossary.html#context-rot">context rot</a>).</li><li>Distinguish four ways of shaping context — <a href="./../../resources/glossary.html#agentsmd">Glossary: AGENTS.md</a> and rules files, <a href="./../../resources/glossary.html#skill">skills</a>, tools over <a href="./../../resources/glossary.html#mcp">MCP</a>, the task prompt — and say when each loads and who wrote it.</li><li>Implement and test an MCP tool over stdio with <a href="./../../resources/glossary.html#json-rpc">JSON-RPC</a> 2.0, validating input and capping output, and connect it to a real agent.</li><li>Write an <code>AGENTS.md</code> for a codebase you didn&#39;t write and measure whether an agent follows it with a small A/B test.</li><li>Read the evidence on AI configuration files critically: what an observational study of 441 repositories can and can&#39;t show.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>Due-date quiz on the week 2 onboarding report (7 min, 🔴 AI off, <a href="./../../assessment/quizzes.html">quizzes</a>) · concept talk: the context window, <code>AGENTS.md</code>/rules/skills, MCP in one slide, context rot, the config-file evidence (25 min, <a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-03.html" target="_blank" rel="noreferrer">slides</a>) · first graduate presentation or reading discussion (20 min) · live demo of one MCP tool call (10 min) · Lab preview (5 min).</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html#lab--mcp-from-scratch-75-min">lab</a> uses the <a href="https://github.com/Boyu-Zhang-UOI/eswa-mcp-from-scratch" target="_blank" rel="noreferrer"><code>mcp-from-scratch</code> kit</a>, a zero-dependency MCP server in about 140 lines: read the protocol by running it, add a tool of your own with validation and tests, and register the server with an agent until it calls your tool. The take-home <a href="./lab.html#assignment--agentsmd-and-an-ab-test">assignment</a> writes the class codebase&#39;s <code>AGENTS.md</code> from the <a href="./../../templates/AGENTS.html">template</a>, then tests it.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Denisov-Blanch et al., <a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">&quot;A Few Pages of Markdown&quot;</a></strong> (arXiv 2608.25241, preprint). Read the abstract, the main results table and the threats to validity. In 441 repositories that adopted coding agents, commits rose 28–38%; agent-first repositories without a committed AI configuration file saw complexity rise 53% against 27% in those with one; and 73.8% of configuration files were never edited after their first commit. Observational.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): State the main claim with one number. Name one alternative explanation for the 53% vs 27% difference the design can&#39;t rule out (think about who commits a config file), and say what data would separate it from the authors&#39; explanation. End with what the 73.8% figure changes about how you&#39;ll maintain your own <code>AGENTS.md</code>, and one question for the Seminar. More readings: <a href="./../../resources/reading-list.html#week-3--context-engineering">reading list, week 3</a>.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>The context is the agent&#39;s whole world.</strong> Each turn the model sees the system prompt, every tool&#39;s name, description and schema, standing instructions, the conversation, and the tool results so far — nothing else. <em>Context engineering</em> is deciding what goes in and what stays out.</li><li><strong>More is not better.</strong> In all 18 models Chroma tested, performance fell as input length grew, and a focused prompt of about 300 tokens beat the full 113K-token one (<a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">Hong et al.</a>). Every line of <code>AGENTS.md</code> and every tool schema is read in every session: it costs tokens, latency and attention.</li><li><strong>Four ways in, four authors.</strong> <code>AGENTS.md</code> and rules files load every session; skills load when a task matches their description; MCP servers add tools whose descriptions are prompts the model reads; the task prompt is yours. Anything in the repository you didn&#39;t write is a stranger&#39;s instructions to your agent (<a href="./../../resources/case-studies.html#a9-the-rules-file-backdoor">case A9</a>); read it first (<a href="./../../setup/safety-contract.html#8-read-before-you-adopt">rule 8</a>).</li><li><strong>MCP is JSON-RPC over a pipe.</strong> A client lists a server&#39;s tools (<code>tools/list</code>) and calls them (<code>tools/call</code>); a stdio server reads one JSON object per line. The kit does an <code>initialize</code> handshake; the current spec no longer requires one, so newer clients may skip it, and the kit answers either way (spec status and SDKs in <a href="./../../TOOLS.html#free-infrastructure">Tool Handout: Free infrastructure</a>). Make tools <strong>narrow</strong> (<code>search_notes</code>, not <code>read_any_file</code>), validate every argument and cap every output; week 4 shows what an over-broad tool costs.</li><li><strong><code>AGENTS.md</code> is advice, not enforcement.</strong> It may lower agents&#39; quality cost (the reading), but nothing makes an agent obey it, so measure compliance and enforce what matters with permissions and sandboxes. Test it with the <a href="./../../resources/agent-patterns.html#the-goldfish-test">Goldfish test</a>: a fresh session gets only the document, and every guess it makes is a defect in it.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>A stdio MCP server prints a startup banner with <code>console.log</code>. What breaks, and why?</li><li>Your <code>AGENTS.md</code> says &quot;run <code>npm test -- [file]</code> before finishing&quot;; in 2 of 3 runs the agent ran the full suite instead. Did it follow the rule? What goes in your results table, and what would you change in the file?</li><li>Why might a 40-line <code>AGENTS.md</code> outperform a 400-line one, even if every line of the long one is true?</li><li>Which of these did you not write, so are a stranger&#39;s instructions to your agent: the codebase&#39;s <code>CONTRIBUTING.md</code>, a repo skill folder, an MCP server&#39;s tool descriptions, an issue the agent reads?</li><li>The reading&#39;s repositories with a configuration file saw complexity rise less. Give one reason that is not &quot;the file caused it&quot;.</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>No MCP-capable agent works:</strong> use MCP Inspector or the kit&#39;s <code>client.mjs</code> for the protocol, and show the checkoff with any agent from <a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a> your or a classmate&#39;s setup supports. Connection problems: <a href="./../../resources/troubleshooting.html#mcp-the-server-wont-connect">troubleshooting</a>.</li><li><strong>Out of free allowance:</strong> run the A/B test on the lab machine&#39;s Ollama or a local model (<a href="./../../setup/local-models.html">local models</a>), same model every run, noted in your report.</li><li><strong>The class codebase won&#39;t build:</strong> write and test <code>AGENTS.md</code> for tasks that need no build (documentation, a test file); see <a href="./../../resources/troubleshooting.html#the-class-codebase-wont-build">troubleshooting</a>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Anthropic Engineering, <a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">&quot;Effective context engineering for AI agents&quot;</a>, and Michigan EECS 498&#39;s <a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">Elephant-Goldfish Model</a>, where the Goldfish test comes from.</li><li>Port <code>search_notes</code> to an official MCP SDK (the kit README&#39;s stretch; <a href="./../../TOOLS.html#free-infrastructure">Tool Handout: Free infrastructure</a> names the current SDK line).</li><li>Previous week: <a href="./../02-inside-agents/">Inside Real Agents</a>. Next week: <a href="./../04-securing-agents/">Securing Agents</a>, where MCP tool descriptions and project files become attack surface.</li></ul>',22)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
